do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4031,"word":"alchemy","meaning":"煉金術","example":"The museum displayed old instruments once used in alchemy.","example_zh":"博物館展示昔日用於煉金術的儀器。","original_meaning":"煉金術","original_example":"The art of alchemy.","original_example_zh":"煉金術。"},{"source_id":4032,"word":"algorithm","meaning":"演算法","example":"The students designed an algorithm to sort blocks by size.","example_zh":"學生設計演算法，依大小排列積木。","original_meaning":"演算法","original_example":"A sorting algorithm.","original_example_zh":"排序演算法。"},{"source_id":4033,"word":"alienation","meaning":"疏離","example":"Moving to an unfamiliar town gave him a sense of alienation.","example_zh":"搬到陌生城鎮，讓他產生疏離感。","original_meaning":"疏離","original_example":"Social alienation.","original_example_zh":"社會疏離。"},{"source_id":4034,"word":"allergy","meaning":"過敏","example":"She told the restaurant staff about her food allergy.","example_zh":"她向餐廳人員說明自己的食物過敏。","original_meaning":"過敏","original_example":"I told the waiter about my peanut allergy before ordering dessert.","original_example_zh":"點甜點前，我先告訴服務生我對花生過敏。"},{"source_id":4035,"word":"allocation","meaning":"分配","example":"The fair allocation of tools helped every group begin work.","example_zh":"公平分配工具，讓每組都能開始工作。","original_meaning":"分配","original_example":"Resource allocation.","original_example_zh":"資源分配"},{"source_id":4036,"word":"alteration","meaning":"變更","example":"A small alteration made the model bridge more stable.","example_zh":"小小變更讓模型橋更穩固。","original_meaning":"變更","original_example":"Make an alteration.","original_example_zh":"進行修改。"},{"source_id":4037,"word":"altruism","meaning":"利他主義","example":"Her altruism showed when she spent the afternoon helping others.","example_zh":"她花整個下午幫助別人，展現利他精神。","original_meaning":"利他主義","original_example":"An act of altruism.","original_example_zh":"一種利他行為。"},{"source_id":4038,"word":"ambassador","meaning":"大使","example":"The ambassador visited the school to discuss cultural exchange.","example_zh":"大使到學校討論文化交流。","original_meaning":"大使","original_example":"The US ambassador.","original_example_zh":"美國大使。"},{"source_id":4039,"word":"ambiguity","meaning":"模糊","example":"The ambiguity of the sketch made the doorway's position unclear.","example_zh":"草圖不夠明確，讓門口位置難以判斷。","original_meaning":"模糊","original_example":"Avoid ambiguity.","original_example_zh":"避免含糊不清。"},{"source_id":4040,"word":"ambulance","meaning":"救護車","example":"The ambulance waited beside the first-aid tent at the festival.","example_zh":"救護車停在節慶急救帳篷旁待命。","original_meaning":"救護車","original_example":"Call an ambulance.","original_example_zh":"叫救護車。"},{"source_id":4041,"word":"ammunition","meaning":"彈藥","example":"The history museum kept the old ammunition in a sealed display case.","example_zh":"歷史博物館把舊彈藥保存在密封展示櫃裡。","original_meaning":"彈藥","original_example":"Run out of ammunition.","original_example_zh":"彈藥用盡。"},{"source_id":4042,"word":"amphibian","meaning":"兩棲動物","example":"The frog is an amphibian that the class studied at the nature center.","example_zh":"青蛙是班上在自然中心研究的一種兩棲動物。","original_meaning":"兩棲動物","original_example":"Frogs are amphibians.","original_example_zh":"青蛙是兩棲動物。"},{"source_id":4043,"word":"amplification","meaning":"放大","example":"The small speaker demonstrated the amplification of the microphone's signal.","example_zh":"小喇叭示範麥克風訊號的放大。","original_meaning":"放大","original_example":"Sound amplification.","original_example_zh":"聲音放大。"},{"source_id":4044,"word":"analytics","meaning":"分析學；資料分析","example":"The library used analytics to understand which books students borrowed most.","example_zh":"圖書館使用資料分析，了解學生最常借閱哪些書。","original_meaning":"分析學","original_example":"Data analytics.","original_example_zh":"資料分析。"},{"source_id":4045,"word":"anarchy","meaning":"無政府","example":"The story described a town falling into anarchy after its government collapsed.","example_zh":"故事描寫政府瓦解後，城鎮陷入無政府狀態。","original_meaning":"無政府","original_example":"Political anarchy.","original_example_zh":"政治無政府狀態。"},{"source_id":4046,"word":"ancestry","meaning":"祖先；家世","example":"She researched her ancestry through old family photographs.","example_zh":"她透過老家族照片研究自己的祖先。","original_meaning":"祖先","original_example":"Trace your ancestry.","original_example_zh":"追溯你的祖先。"},{"source_id":4047,"word":"anesthesia","meaning":"麻醉","example":"The medical exhibit explained the history of anesthesia.","example_zh":"醫學展覽介紹麻醉的歷史。","original_meaning":"麻醉","original_example":"Under anesthesia.","original_example_zh":"在麻醉下。"},{"source_id":4048,"word":"animation","meaning":"動畫","example":"The students created an animation showing a seed growing into a tree.","example_zh":"學生製作動畫，呈現種子長成樹木的過程。","original_meaning":"動畫","original_example":"Computer animation.","original_example_zh":"電腦動畫。"},{"source_id":4049,"word":"annex","meaning":"吞併","example":"The history map showed how the empire sought to annex the neighboring territory.","example_zh":"歷史地圖顯示帝國如何企圖吞併鄰近領土。","original_meaning":"吞併","original_example":"Annex the territory.","original_example_zh":"吞併該領土。"},{"source_id":4050,"word":"annotation","meaning":"註解","example":"Her annotation explained a difficult phrase in the poem.","example_zh":"她的註解說明詩裡一個難懂的片語。","original_meaning":"註解","original_example":"Add annotations.","original_example_zh":"添加註解。"},{"source_id":4051,"word":"anonymity","meaning":"匿名","example":"The survey protected the students' anonymity by collecting no names.","example_zh":"調查不收集姓名，以保護學生匿名身分。","original_meaning":"匿名","original_example":"Maintain anonymity.","original_example_zh":"保持匿名。"},{"source_id":4052,"word":"antagonist","meaning":"對手","example":"The play's antagonist opposed the hero's plan to save the garden.","example_zh":"劇中的對手反對主角拯救花園的計畫。","original_meaning":"對手","original_example":"The story antagonist.","original_example_zh":"故事中的反派角色。"},{"source_id":4053,"word":"antecedent","meaning":"先例；先行事物","example":"The village garden was an antecedent of the town's later public parks.","example_zh":"村莊花園是城鎮後來公共公園的前身。","original_meaning":"先例","original_example":"A historical antecedent.","original_example_zh":"歷史先例。"},{"source_id":4054,"word":"antibiotic","meaning":"抗生素","example":"The pharmacist checked the prescribed antibiotic before handing over the package.","example_zh":"藥師交付藥品前，先核對處方中的抗生素。","original_meaning":"抗生素","original_example":"Take antibiotics.","original_example_zh":"服用抗生素。"},{"source_id":4055,"word":"antidote","meaning":"解毒劑","example":"The medical exhibit described the development of an antidote.","example_zh":"醫學展覽介紹一種解毒劑的研發。","original_meaning":"解毒劑","original_example":"An antidote for poison.","original_example_zh":"解毒劑。"},{"source_id":4056,"word":"antiquated","meaning":"過時的","example":"The museum's antiquated printing press still fascinated visitors.","example_zh":"博物館裡那臺老式印刷機仍令訪客著迷。","original_meaning":"過時的","original_example":"Antiquated methods.","original_example_zh":"過時的做法。"},{"source_id":4057,"word":"antiseptic","meaning":"抗菌劑；消毒劑","example":"The nurse checked the sealed antiseptic container in the supply cabinet.","example_zh":"護理師檢查用品櫃中密封的消毒劑容器。","original_meaning":"防腐劑","original_example":"Apply antiseptic.","original_example_zh":"塗抹消毒劑。"},{"source_id":4058,"word":"apostle","meaning":"使徒","example":"The painting portrayed an apostle teaching a gathered community.","example_zh":"畫作描繪一位使徒向聚集的人群傳道。","original_meaning":"使徒","original_example":"An apostle of peace.","original_example_zh":"和平的使者。"},{"source_id":4059,"word":"appendix","meaning":"附錄","example":"The report's appendix contained detailed drawings of the bridge.","example_zh":"報告附錄收錄橋梁的詳細圖面。","original_meaning":"附錄","original_example":"Check the appendix.","original_example_zh":"請查閱附錄。"},{"source_id":4060,"word":"applause","meaning":"掌聲","example":"Warm applause filled the hall after the final song.","example_zh":"最後一首歌結束後，熱烈掌聲充滿禮堂。","original_meaning":"掌聲","original_example":"Thunderous applause.","original_example_zh":"雷鳴般的掌聲。"},{"source_id":4061,"word":"applicant","meaning":"申請者；求職者","example":"The applicant brought her portfolio to the interview.","example_zh":"求職者帶著作品集參加面試。","original_meaning":"申請者；求職者","original_example":"Each applicant brought a résumé and waited quietly outside the interview room.","original_example_zh":"每位求職者都帶著履歷，在面試室外安靜等候。"},{"source_id":4062,"word":"apprenticeship","meaning":"學徒制","example":"His apprenticeship with a carpenter taught him careful craftsmanship.","example_zh":"他跟隨木匠當學徒，學會細心的工藝。","original_meaning":"學徒制","original_example":"Serve an apprenticeship.","original_example_zh":"擔任學徒。"},{"source_id":4063,"word":"aquarium","meaning":"水族館","example":"The students watched the sea turtles at the aquarium.","example_zh":"學生在水族館觀看海龜。","original_meaning":"水族館","original_example":"Visit the aquarium.","original_example_zh":"參觀水族館。"},{"source_id":4064,"word":"arbitration","meaning":"仲裁","example":"The two companies used arbitration to settle their disagreement.","example_zh":"兩家公司以仲裁解決爭議。","original_meaning":"仲裁","original_example":"Go to arbitration.","original_example_zh":"進行仲裁。"},{"source_id":4065,"word":"archaeology","meaning":"考古學","example":"The archaeology workshop taught students how to examine pottery fragments.","example_zh":"考古學工作坊教學生檢視陶器碎片。","original_meaning":"考古學","original_example":"Study archaeology.","original_example_zh":"研讀考古學。"},{"source_id":4066,"word":"architect","meaning":"建築師","example":"The architect designed a library with wide windows and accessible paths.","example_zh":"建築師設計一座有寬窗與無障礙通道的圖書館。","original_meaning":"建築師","original_example":"A famous architect.","original_example_zh":"一位著名的建築師。"},{"source_id":4067,"word":"aristocracy","meaning":"貴族制度；貴族階級","example":"The exhibit explored the privileges of the aristocracy in the old kingdom.","example_zh":"展覽探討古王國貴族階級的特權。","original_meaning":"貴族制度","original_example":"The aristocracy ruled.","original_example_zh":"貴族階級掌權。"},{"source_id":4068,"word":"arithmetic","meaning":"算術","example":"The students used counters to practice arithmetic.","example_zh":"學生用計數片練習算術。","original_meaning":"算術","original_example":"Basic arithmetic.","original_example_zh":"基礎算術。"},{"source_id":4069,"word":"armistice","meaning":"停戰","example":"The museum displayed the agreement that marked the armistice.","example_zh":"博物館展示標誌停戰的協議。","original_meaning":"停戰","original_example":"Sign an armistice.","original_example_zh":"簽署停戰協定。"},{"source_id":4070,"word":"articulation","meaning":"表達","example":"Her clear articulation helped the audience follow the explanation.","example_zh":"她清晰的表達幫助聽眾理解說明。","original_meaning":"表達","original_example":"Clear articulation.","original_example_zh":"清晰的發音。"},{"source_id":4071,"word":"aspiration","meaning":"抱負","example":"Her aspiration was to become an engineer who designed safer bridges.","example_zh":"她的抱負是成為設計更安全橋梁的工程師。","original_meaning":"抱負","original_example":"Career aspirations.","original_example_zh":"職業抱負。"},{"source_id":4072,"word":"assemble","meaning":"組裝","example":"We will assemble the model house after sorting all the parts.","example_zh":"把所有零件分類後，我們將組裝模型屋。","original_meaning":"組裝","original_example":"Assemble the parts.","original_example_zh":"組裝零件。"},{"source_id":4073,"word":"assurance","meaning":"保證","example":"The guide's assurance helped the nervous visitors feel at ease.","example_zh":"嚮導的保證讓緊張訪客安心。","original_meaning":"保證","original_example":"Give assurance.","original_example_zh":"給予保證。"},{"source_id":4074,"word":"asteroid","meaning":"小行星","example":"The exhibit displayed a model of an asteroid orbiting the Sun.","example_zh":"展覽展示繞太陽運行的小行星模型。","original_meaning":"小行星","original_example":"An asteroid belt.","original_example_zh":"小行星帶。"},{"source_id":4075,"word":"atheism","meaning":"無神論","example":"The philosophy lesson discussed atheism alongside other views about religion.","example_zh":"哲學課把無神論與其他宗教觀點一併討論。","original_meaning":"無神論","original_example":"The rise of atheism.","original_example_zh":"無神論的興起。"},{"source_id":4076,"word":"attic","meaning":"閣樓","example":"They found old family photographs in the attic.","example_zh":"他們在閣樓找到老家族照片。","original_meaning":"閣樓","original_example":"Store it in the attic.","original_example_zh":"把它存放在閣樓裡。"},{"source_id":4077,"word":"attribution","meaning":"歸因；作品歸屬","example":"The curator questioned the painting's attribution to the famous artist.","example_zh":"策展人質疑這幅畫是否真出自那位知名藝術家。","original_meaning":"歸因","original_example":"Proper attribution.","original_example_zh":"正確的引用。"},{"source_id":4078,"word":"auditorium","meaning":"禮堂","example":"The orchestra rehearsed in the school auditorium.","example_zh":"管弦樂團在學校禮堂排練。","original_meaning":"禮堂","original_example":"The school auditorium.","original_example_zh":"學校禮堂。"},{"source_id":4079,"word":"automation","meaning":"自動化","example":"The factory used automation to sort packages by size.","example_zh":"工廠利用自動化依大小分類包裹。","original_meaning":"自動化","original_example":"Factory automation.","original_example_zh":"工廠自動化。"},{"source_id":4080,"word":"backdrop","meaning":"背景幕","example":"The painted forest formed the backdrop for the school play.","example_zh":"畫出的森林成為校園戲劇的背景幕。","original_meaning":"背景幕","original_example":"Against the backdrop.","original_example_zh":"以……為背景。"},{"source_id":4081,"word":"bacteria","meaning":"細菌","example":"The biology exhibit used enlarged models to represent bacteria.","example_zh":"生物展覽用放大模型呈現細菌。","original_meaning":"細菌","original_example":"Harmful bacteria.","original_example_zh":"有害細菌。"},{"source_id":4082,"word":"baptism","meaning":"洗禮","example":"The painting depicted a baptism beside a quiet river.","example_zh":"畫作描繪寧靜河畔的一場洗禮。","original_meaning":"洗禮","original_example":"A baptism ceremony.","original_example_zh":"洗禮儀式。"},{"source_id":4083,"word":"barometer","meaning":"氣壓計","example":"The students checked the barometer before recording the weather.","example_zh":"學生記錄天氣前先查看氣壓計。","original_meaning":"氣壓計","original_example":"A social barometer.","original_example_zh":"社會風向標。"},{"source_id":4084,"word":"barracks","meaning":"軍營","example":"The museum preserved a former barracks as a historic building.","example_zh":"博物館把昔日軍營保存為歷史建築。","original_meaning":"軍營","original_example":"Military barracks.","original_example_zh":"軍營。"},{"source_id":4085,"word":"baseline","meaning":"基準線；基準","example":"We recorded a baseline measurement before testing the new filter.","example_zh":"我們在測試新濾器前先記錄基準測量值。","original_meaning":"基準線","original_example":"Establish a baseline.","original_example_zh":"建立基準線。"},{"source_id":4086,"word":"battlefield","meaning":"戰場","example":"The former battlefield is now a quiet memorial park.","example_zh":"昔日戰場如今是寧靜的紀念公園。","original_meaning":"戰場","original_example":"On the battlefield.","original_example_zh":"在戰場上。"},{"source_id":4087,"word":"beneficiary","meaning":"受益人；受益者","example":"The rural school was the main beneficiary of the book donation.","example_zh":"那所鄉村學校是贈書活動的主要受益者。","original_meaning":"受益人","original_example":"The beneficiary of a will.","original_example_zh":"遺囑的受益人。"},{"source_id":4088,"word":"benevolent","meaning":"慈善的；仁慈的","example":"The benevolent shopkeeper donated warm coats to the community center.","example_zh":"仁慈的店主捐贈保暖外套給社區中心。","original_meaning":"慈善的","original_example":"A benevolent act.","original_example_zh":"一項善舉。"},{"source_id":4089,"word":"bereavement","meaning":"喪親","example":"Friends supported the family through their bereavement.","example_zh":"朋友陪伴那個家庭度過喪親之痛。","original_meaning":"喪親","original_example":"A time of bereavement.","original_example_zh":"一段喪親的時期。"},{"source_id":4090,"word":"beverage","meaning":"飲料","example":"She chose a warm beverage after the chilly walk.","example_zh":"寒冷天氣散步後，她選了一杯熱飲。","original_meaning":"飲料","original_example":"A refreshing beverage.","original_example_zh":"一杯清爽的飲料。"},{"source_id":4091,"word":"biodegradable","meaning":"可生物分解的","example":"The class compared biodegradable packaging with ordinary plastic.","example_zh":"班上比較可生物分解包材與一般塑膠。","original_meaning":"可分解的","original_example":"Biodegradable packaging.","original_example_zh":"可生物降解的包裝。"},{"source_id":4092,"word":"biologist","meaning":"生物學家","example":"The biologist observed the birds without disturbing their nests.","example_zh":"生物學家觀察鳥類，同時避免打擾鳥巢。","original_meaning":"生物學家","original_example":"A marine biologist.","original_example_zh":"一位海洋生物學家。"},{"source_id":4093,"word":"biotechnology","meaning":"生物科技","example":"The biotechnology exhibit explained how living cells can be used in research.","example_zh":"生物科技展覽解說活細胞如何用於研究。","original_meaning":"生物科技","original_example":"Advances in biotechnology.","original_example_zh":"生物技術的進展。"},{"source_id":4094,"word":"blackmail","meaning":"勒索","example":"The shopkeeper reported the blackmail to the police.","example_zh":"店主向警方報案，說明遭到勒索。","original_meaning":"勒索","original_example":"Commit blackmail.","original_example_zh":"進行勒索。"},{"source_id":4095,"word":"blasphemy","meaning":"褻瀆","example":"The discussion examined why some people regarded the remark as blasphemy.","example_zh":"討論探究為何有些人認為那句話構成褻瀆。","original_meaning":"褻瀆","original_example":"An act of blasphemy.","original_example_zh":"一種褻瀆神明之舉。"},{"source_id":4096,"word":"blockade","meaning":"封鎖","example":"The historical map showed a blockade that prevented ships from entering the harbor.","example_zh":"歷史地圖顯示阻止船隻進港的封鎖。","original_meaning":"封鎖","original_example":"A naval blockade.","original_example_zh":"海上封鎖。"},{"source_id":4097,"word":"bombardment","meaning":"轟炸","example":"The exhibit documented the damage caused by bombardment during the war.","example_zh":"展覽記錄戰時轟炸造成的破壞。","original_meaning":"轟炸","original_example":"Under bombardment.","original_example_zh":"遭受猛烈轟炸。"},{"source_id":4098,"word":"botany","meaning":"植物學","example":"The botany lesson focused on the shapes of leaves.","example_zh":"植物學課聚焦葉片形狀。","original_meaning":"植物學","original_example":"Study botany.","original_example_zh":"研讀植物學。"},{"source_id":4099,"word":"boulevard","meaning":"大道","example":"A tree-lined boulevard led to the town's museum.","example_zh":"林蔭大道通往城鎮博物館。","original_meaning":"大道","original_example":"Walk down the boulevard.","original_example_zh":"沿著林蔭大道走。"},{"source_id":4100,"word":"bourgeoisie","meaning":"資產階級","example":"The history lesson explored the growing influence of the bourgeoisie.","example_zh":"歷史課探討資產階級日益增長的影響力。","original_meaning":"資產階級","original_example":"The bourgeoisie class.","original_example_zh":"資產階級。"},{"source_id":4101,"word":"brewery","meaning":"釀酒廠","example":"The industrial museum preserved machinery from an old brewery.","example_zh":"工業博物館保存老釀酒廠的機械。","original_meaning":"釀酒廠","original_example":"A craft brewery.","original_example_zh":"一家精釀啤酒廠。"},{"source_id":4102,"word":"brigade","meaning":"旅","example":"The exhibit showed equipment once used by an army brigade.","example_zh":"展覽展示某陸軍旅曾使用的裝備。","original_meaning":"旅","original_example":"A fire brigade.","original_example_zh":"一支消防隊。"},{"source_id":4103,"word":"brochure","meaning":"小冊子","example":"The guide handed each visitor a brochure about the nature reserve.","example_zh":"導覽員發給每位訪客一本自然保護區小冊子。","original_meaning":"小冊子","original_example":"Read the brochure.","original_example_zh":"閱讀這份小冊子。"},{"source_id":4104,"word":"bronze","meaning":"青銅","example":"The sculptor cast a small bird in bronze.","example_zh":"雕塑家以青銅鑄造一隻小鳥。","original_meaning":"青銅","original_example":"The Bronze Age.","original_example_zh":"青銅時代。"},{"source_id":4105,"word":"brutality","meaning":"殘暴","example":"The novel condemned the brutality of the unjust ruler.","example_zh":"小說譴責不公統治者的殘暴。","original_meaning":"殘暴","original_example":"Police brutality.","original_example_zh":"警察的暴力行為。"},{"source_id":4106,"word":"bureaucrat","meaning":"官僚","example":"The bureaucrat reviewed the application for the new public library.","example_zh":"官員審查興建公共圖書館的申請。","original_meaning":"官僚","original_example":"A government bureaucrat.","original_example_zh":"一位政府官僚。"},{"source_id":4107,"word":"calibration","meaning":"校準","example":"The technician checked the balance's calibration with standard weights.","example_zh":"技術人員用標準砝碼檢查天平校準。","original_meaning":"校準","original_example":"Instrument calibration.","original_example_zh":"儀器校準。"},{"source_id":4108,"word":"calligraphy","meaning":"書法","example":"The students practiced calligraphy with brushes and ink.","example_zh":"學生用毛筆與墨練習書法。","original_meaning":"書法","original_example":"Practice calligraphy.","original_example_zh":"練習書法。"},{"source_id":4109,"word":"candidacy","meaning":"候選資格；參選","example":"She announced her candidacy for president of the student council.","example_zh":"她宣布參選學生會會長。","original_meaning":"候選資格","original_example":"Announce candidacy.","original_example_zh":"宣布參選。"},{"source_id":4110,"word":"caravan","meaning":"商隊","example":"The caravan crossed the dry plain with its supplies carefully packed.","example_zh":"商隊帶著妥善打包的物資穿越乾燥平原。","original_meaning":"商隊","original_example":"A desert caravan.","original_example_zh":"一支沙漠商隊。"},{"source_id":4111,"word":"carbonate","meaning":"碳酸鹽","example":"The geologist identified the mineral as a carbonate.","example_zh":"地質學家辨認出這種礦物屬於碳酸鹽。","original_meaning":"碳酸鹽","original_example":"Calcium carbonate.","original_example_zh":"碳酸鈣。"},{"source_id":4112,"word":"cardiovascular","meaning":"心血管的","example":"The cardiovascular model showed the heart and major blood vessels.","example_zh":"心血管模型展示心臟與主要血管。","original_meaning":"心血管的","original_example":"Cardiovascular disease.","original_example_zh":"心血管疾病。"},{"source_id":4113,"word":"caricature","meaning":"漫畫","example":"The artist drew a playful caricature of the fictional mayor.","example_zh":"畫家為虛構市長畫了一幅詼諧誇張的漫畫。","original_meaning":"漫畫","original_example":"A political caricature.","original_example_zh":"一幅政治諷刺畫。"},{"source_id":4114,"word":"carnivore","meaning":"肉食動物","example":"The zoology exhibit described the fox as a carnivore.","example_zh":"動物學展覽把狐狸介紹為肉食動物。","original_meaning":"肉食動物","original_example":"Lions are carnivores.","original_example_zh":"獅子是肉食動物。"},{"source_id":4115,"word":"cartography","meaning":"製圖學","example":"The cartography workshop taught students to represent hills on a map.","example_zh":"製圖學工作坊教學生在地圖上表現山丘。","original_meaning":"製圖學","original_example":"The art of cartography.","original_example_zh":"製圖學。"},{"source_id":4116,"word":"casualty","meaning":"傷亡；傷者","example":"The rescue team carried a casualty to the first-aid tent.","example_zh":"救援隊把一名傷者送到急救帳篷。","original_meaning":"傷亡","original_example":"War casualties.","original_example_zh":"戰爭傷亡。"},{"source_id":4117,"word":"catastrophic","meaning":"災難性的","example":"The catastrophic storm damaged many roofs in the village.","example_zh":"災難性的風暴損壞村莊許多屋頂。","original_meaning":"災難性的","original_example":"Catastrophic failure.","original_example_zh":"災難性的失敗。"},{"source_id":4118,"word":"categorization","meaning":"分類","example":"The categorization of the books made the library easier to use.","example_zh":"把書籍分類後，圖書館更方便使用。","original_meaning":"分類","original_example":"A system of categorization.","original_example_zh":"分類系統。"},{"source_id":4119,"word":"cathedral","meaning":"大教堂","example":"The visitors admired the cathedral's tall stone arches.","example_zh":"訪客欣賞大教堂高聳的石拱。","original_meaning":"大教堂","original_example":"A gothic cathedral.","original_example_zh":"一座哥德式大教堂。"},{"source_id":4120,"word":"centralization","meaning":"集中化","example":"The lesson examined the centralization of decisions in one office.","example_zh":"課程探討把決策集中於單一辦公室的制度。","original_meaning":"集中化","original_example":"Government centralization.","original_example_zh":"政府中央集權。"},{"source_id":4121,"word":"chaplain","meaning":"牧師；院牧","example":"The chaplain offered quiet support to the family at the hospital.","example_zh":"醫院牧師安靜陪伴那個家庭。","original_meaning":"牧師","original_example":"A military chaplain.","original_example_zh":"一位軍隊牧師。"},{"source_id":4122,"word":"choreography","meaning":"編舞","example":"The choreography combined graceful steps with clear group patterns.","example_zh":"編舞結合優雅舞步與清楚的團體隊形。","original_meaning":"編舞","original_example":"Dance choreography.","original_example_zh":"舞蹈編排。"},{"source_id":4123,"word":"chromosome","meaning":"染色體","example":"The biology model showed a chromosome carrying genetic information.","example_zh":"生物模型展示攜帶遺傳資訊的染色體。","original_meaning":"染色體","original_example":"Human chromosomes.","original_example_zh":"人類染色體。"},{"source_id":4124,"word":"chronology","meaning":"年代學；年代順序","example":"The exhibit arranged the inventions in a clear chronology.","example_zh":"展覽以清楚年代順序排列各項發明。","original_meaning":"年代學","original_example":"In chronological order.","original_example_zh":"按時間順序排列。"},{"source_id":4125,"word":"cinematography","meaning":"攝影術；電影攝影","example":"The film's cinematography made the mountain landscape look magnificent.","example_zh":"影片的攝影讓山景顯得壯麗。","original_meaning":"攝影術","original_example":"Award-winning cinematography.","original_example_zh":"屢獲殊榮的攝影藝術。"},{"source_id":4126,"word":"circulation","meaning":"流通","example":"The circulation of library books increased after the reading festival.","example_zh":"閱讀節後，圖書館書籍流通量增加。","original_meaning":"流通","original_example":"Blood circulation.","original_example_zh":"血液循環。"},{"source_id":4127,"word":"circumference","meaning":"圓周","example":"We measured the wheel's circumference with a flexible tape.","example_zh":"我們用軟尺測量輪子的圓周。","original_meaning":"圓周","original_example":"The circumference of a circle.","original_example_zh":"圓的周長。"},{"source_id":4128,"word":"citizenship","meaning":"公民身份","example":"The ceremony marked the new residents' acquisition of citizenship.","example_zh":"儀式標誌新居民取得公民身分。","original_meaning":"公民身份","original_example":"Apply for citizenship.","original_example_zh":"申請公民身份。"},{"source_id":4129,"word":"classification","meaning":"分類","example":"The classification of rocks helped us compare their properties.","example_zh":"岩石分類幫助我們比較各種性質。","original_meaning":"分類","original_example":"A classification system.","original_example_zh":"一套分類系統。"},{"source_id":4130,"word":"clergy","meaning":"神職人員","example":"The clergy welcomed visitors to the historic church.","example_zh":"神職人員歡迎訪客參觀歷史教堂。","original_meaning":"神職人員","original_example":"Members of the clergy.","original_example_zh":"神職人員。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-alchemy-01-v1","level":"senior","word":"alchemy","sort_order":1,"sense":"煉金術","alt_zh":"高中生在歷史博物館觀看古老密封玻璃器皿與金屬工具，無實驗操作。","example":"The museum displayed old instruments once used in alchemy.","example_zh":"博物館展示昔日用於煉金術的儀器。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alchemy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-algorithm-01-v1","level":"senior","word":"algorithm","sort_order":1,"sense":"演算法","alt_zh":"高中生與老師用無字流程圖與不同大小積木示範逐步排序。","example":"The students designed an algorithm to sort blocks by size.","example_zh":"學生設計演算法，依大小排列積木。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/algorithm-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-alienation-01-v1","level":"senior","word":"alienation","sort_order":1,"sense":"疏離","alt_zh":"剛轉學的高中生獨坐校園長椅，遠處同學友善準備走來邀請他。","example":"Moving to an unfamiliar town gave him a sense of alienation.","example_zh":"搬到陌生城鎮，讓他產生疏離感。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alienation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-allergy-01-v1","level":"senior","word":"allergy","sort_order":1,"sense":"過敏","alt_zh":"成年顧客在乾淨餐廳向服務員仔細說明食物需求，無過敏症狀或治療指示。","example":"She told the restaurant staff about her food allergy.","example_zh":"她向餐廳人員說明自己的食物過敏。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/allergy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-allocation-01-v1","level":"senior","word":"allocation","sort_order":1,"sense":"分配","alt_zh":"老師將等量安全工具分配給幾組高中生，桌面整齊有序。","example":"The fair allocation of tools helped every group begin work.","example_zh":"公平分配工具，讓每組都能開始工作。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/allocation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-alteration-01-v1","level":"senior","word":"alteration","sort_order":1,"sense":"變更","alt_zh":"高中生在老師指導下調整木模型橋的一根支架，完成後橋面平直。","example":"A small alteration made the model bridge more stable.","example_zh":"小小變更讓模型橋更穩固。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alteration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-altruism-01-v1","level":"senior","word":"altruism","sort_order":1,"sense":"利他主義","alt_zh":"高中女生在社區中心熱心幫長者搬書、整理物資，無求報酬。","example":"Her altruism showed when she spent the afternoon helping others.","example_zh":"她花整個下午幫助別人，展現利他精神。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/altruism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ambassador-01-v1","level":"senior","word":"ambassador","sort_order":1,"sense":"大使","alt_zh":"成年外交代表在高中教室與學生分享不同地區的藝術與書籍，無真實政黨。","example":"The ambassador visited the school to discuss cultural exchange.","example_zh":"大使到學校討論文化交流。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ambassador-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ambiguity-01-v1","level":"senior","word":"ambiguity","sort_order":1,"sense":"模糊","alt_zh":"高中生困惑地看模型屋草圖上模糊不清的門口線條，老師在旁討論。","example":"The ambiguity of the sketch made the doorway's position unclear.","example_zh":"草圖不夠明確，讓門口位置難以判斷。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ambiguity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ambulance-01-v1","level":"senior","word":"ambulance","sort_order":1,"sense":"救護車","alt_zh":"乾淨救護車停在社區活動急救帳篷旁，成年救護人員整備，無傷者。","example":"The ambulance waited beside the first-aid tent at the festival.","example_zh":"救護車停在節慶急救帳篷旁待命。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ambulance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ammunition-01-v1","level":"senior","word":"ammunition","sort_order":1,"sense":"彈藥","alt_zh":"高中生與導覽員從遠處觀看鎖好展櫃內少量歷史停用彈藥，無武器操作或製造細節。","example":"The history museum kept the old ammunition in a sealed display case.","example_zh":"歷史博物館把舊彈藥保存在密封展示櫃裡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ammunition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-amphibian-01-v1","level":"senior","word":"amphibian","sort_order":1,"sense":"兩棲動物","alt_zh":"高中生在自然中心從安全觀察區看水邊青蛙與蝌蚪教學模型。","example":"The frog is an amphibian that the class studied at the nature center.","example_zh":"青蛙是班上在自然中心研究的一種兩棲動物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/amphibian-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-amplification-01-v1","level":"senior","word":"amplification","sort_order":1,"sense":"放大","alt_zh":"音樂老師向高中生展示安全低音量麥克風、放大器與小喇叭連接。","example":"The small speaker demonstrated the amplification of the microphone's signal.","example_zh":"小喇叭示範麥克風訊號的放大。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/amplification-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-analytics-01-v1","level":"senior","word":"analytics","sort_order":1,"sense":"分析學；資料分析","alt_zh":"成年圖書館員與高中生查看無數字借